"<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width'><title>U</title><header style='background:#1a6d2f;color:#fff;padding:8px;text-align:center;font-weight:900'>Uwashusema Mahida</header><div style='padding:4px'><select id=m><option value=11>Nov<option value=12>Des</select><input id=y value=2026><button onclick=R()>Sawa</button><div style='display:flex;gap:2px'><div style='flex:1;background:#2e7d32;color:#fff;padding:4px;text-align:center'>MAPATO<br><span id=a>0</span></div><div style='flex:1;background:#c00;color:#fff;padding:4px;text-align:center'>MATUMIZI<br><span id=b>0</span></div><div style='flex:1;background:#1565c0;color:#fff;padding:4px;text-align:center'>SALIO<br><span id=c>0</span></div></div><div style='background:#fff;padding:3px'><b>Wanachama <button onclick=W()>+ Mpya</button></b><div id=wl></div></div><div style='background:#fff;padding:3px'><select id=sw></select><select id=sa><option value=hisa>Hisa<option value=ada>Ada<option value=marejesho>Marejesho<option value=faini_ada>Riba Ada<option value=faini_marejesho>Riba Rejesho<option value=michango>Michango<option value=mkopo_toka>Mkopo</select><input id=kv><button onclick=M()>Hifadhi</button></div><div style='background:#fff;padding:3px'><button onclick=E()>Pakua Excel (4)</button><div id=hi></div></div></div><script>D=JSON.parse(localStorage.v8||'null')||{w:[],m:[]};function S(){localStorage.v8=JSON.stringify(D);R()}function W(){j=prompt('Jina:');if(j){D.w.push({j:j});S()}}function M(){w=sw.value;a=sa.value;k=+kv.value;if(!w||!k)return alert('Jaza');D.m.push({w:w,a:a,k:k,mm:+m.value,yy:+y.value});if(a=='mkopo_toka'){f=Math.round(k*0.05);D.m.push({w:w,a:'fomu',k:f,mm:+m.value,yy:+y.value})}kv.value='';S()}function R(){mm=+m.value;yy=+y.value;mi=D.m.filter(x=>x.mm==mm&&x.yy==yy);mp=0;mt=0;mi.forEach(t=>{if(['hisa','ada','marejesho','faini_ada','faini_marejesho','fomu','michango'].includes(t.a))mp+=t.k;if(t.a=='mkopo_toka')mt+=t.k});a.innerText=mp;b.innerText=mt;c.innerText=mp-mt;wl.innerHTML=sw.innerHTML='';if(!D.w.length)wl.innerHTML='Hakuna';D.w.forEach((x,i)=>{wl.innerHTML+=x.j+' <button onclick=\"D.w.splice('+i+',1);S()\">X</button><br>';sw.innerHTML+='<option>'+x.j+'</option>'});hi.innerHTML='';mi.slice().reverse().forEach(t=>{hi.innerHTML+=t.w+'-'+t.a+'-'+t.k+'<br>'})}function E(){all=D.m.filter(x=>x.mm==+m.value&&x.yy==+y.value);if(!all.length)return alert('Hakuna');function Rr(r){s='<Row>';r.forEach(v=>{s+='<Cell><Data ss:Type=\"String\">'+v+'</Data></Cell>'});return s+'</Row>'}r1=[['Jina','Ada','Riba']];r2=[['Jina','Mkopo','Fomu','Rejesho','Riba']];r3=[['Jina','Hisa']];r4=[['Jina','Michango']];am={};ar={};dm={};hm={};mc={};D.w.forEach(x=>{am[x.j]=0;ar[x.j]=0;dm[x.j]={c:0,f:0,r:0,fr:0};hm[x.j]=0;mc[x.j]=0});all.forEach(t=>{if(t.a=='ada')am[t.w]+=t.k;if(t.a=='faini_ada')ar[t.w]+=t.k;if(t.a=='mkopo_toka')dm[t.w].c+=t.k;if(t.a=='fomu')dm[t.w].f+=t.k;if(t.a=='marejesho')dm[t.w].r+=t.k;if(t.a=='faini_marejesho')dm[t.w].fr+=t.k;if(t.a=='hisa')hm[t.w]+=t.k;if(t.a=='michango')mc[t.w]+=t.k});for(j in am)r1.push([j,am[j],ar[j]]);for(j in dm){d=dm[j];if(d.c>0)r2.push([j,d.c,d.f,d.r,d.fr])}for(j in hm)if(hm[j])r3.push([j,hm[j]]);for(j in mc)if(mc[j])r4.push([j,mc[j]]);function Sh(n,rows){h='<Worksheet ss:Name=\"'+n+'\"><Table>';rows.forEach(r=>{h+=Rr(r)});return h+'</Table></Worksheet>'}xml='<?xml version=\"1.0\"?><Workbook xmlns=\"urn:schemas-microsoft-com:office:spreadsheet\" xmlns:ss=\"urn:schemas-microsoft-com:office:spreadsheet\">'+Sh('Ada',r1)+Sh('Mikopo',r2)+Sh('Hisa',r3)+Sh('Michango',r4)+'</Workbook>';b=new Blob([xml],{type:'application/vnd.ms-excel'});u=URL.createObjectURL(b);a=document.createElement('a');a.href=u;a.download='Uwashusema.xls';a.click()}m.value=11;R();</script>"
